const CFG=window.PM_CONFIG||{},db=window.supabase?.createClient(CFG.SUPABASE_URL,CFG.SUPABASE_ANON_KEY);const $=id=>document.getElementById(id),money=n=>'৳'+Number(n||0).toLocaleString('en-BD'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let user=null,isMainAdmin=false,products=[],categories=[],orders=[],orderItems=[],coupons=[],bikeModels=[],filter='all';let selectedGalleryFiles=[];function msg(id,t){$(id).textContent=t}function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2300)}function page(p){if(p==='login-history'&&!isMainAdmin){p='dashboard';toast('এই তথ্য শুধু Main Admin দেখতে পারবেন।')}document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('pageTitle').textContent=({dashboard:'ড্যাশবোর্ড',products:'প্রোডাক্টস',categories:'ক্যাটাগরি',orders:'অর্ডার',customers:'কাস্টমার',reports:'বিক্রির রিপোর্ট',coupons:'কুপন ম্যানেজমেন্ট',settings:'সেটিংস','bike-models':'Bike Models','login-history':'Admin Login History'})[p]||p;if(p==='bike-models')renderBikeModels();if(p==='orders')renderOrders();if(p==='reports')renderReports();if(p==='coupons')renderCoupons();if(p==='login-history')loadLoginHistory()}async function authView(recordLogin=false){if(!user){$('loginScreen').hidden=false;$('app').hidden=true;return}try{const {data,error}=await db.from('profiles').select('role').eq('id',user.id).single();if(error){msg('loginMsg','প্রোফাইল যাচাই করা যায়নি: '+error.message);await db.auth.signOut();user=null;$('loginScreen').hidden=false;$('app').hidden=true;return}if(!['admin','main_admin'].includes(data?.role)){msg('loginMsg','লগইন হয়েছে, কিন্তু এই অ্যাকাউন্টটি Admin হিসেবে অনুমোদিত নয়।');await db.auth.signOut();user=null;$('loginScreen').hidden=false;$('app').hidden=true;return}isMainAdmin=data.role==='main_admin';$('loginHistoryNav').hidden=!isMainAdmin;$('loginScreen').hidden=true;$('app').hidden=false;$('adminEmail').textContent=user.email;$('settingsEmail').textContent=user.email;if(recordLogin){const audit=await db.rpc('record_admin_login');if(audit.error)toast('Login History সংরক্ষণ হয়নি। Supabase-এ admin-login-history-migration.sql চালানো হয়েছে কি না দেখুন।')}page('dashboard');await refresh();await loadStoreSettings()}catch(err){msg('loginMsg','Admin যাচাইয়ে সমস্যা: '+(err.message||String(err)));$('loginScreen').hidden=false;$('app').hidden=true}}async function login(e){e.preventDefault();if(!db){msg('loginMsg','Supabase সংযোগ পাওয়া যায়নি। config.js এবং নেটওয়ার্ক পরীক্ষা করুন।');return}msg('loginMsg','লগইন হচ্ছে...');const f=new FormData(e.target);try{const {data,error}=await db.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error){msg('loginMsg','লগইন ব্যর্থ: '+error.message);return}user=data.user;await authView(true)}catch(err){msg('loginMsg','লগইন ত্রুটি: '+(err.message||String(err)))}}async function refresh(){const [p,c,o,i,k,bm]=await Promise.all([db.from('products').select('*').order('created_at',{ascending:false}),db.from('categories').select('name,parent_name').order('name'),db.from('orders').select('*').order('created_at',{ascending:false}),db.from('order_items').select('order_id,product_name,unit_price,quantity'),db.from('coupons').select('*').order('created_at',{ascending:false}),db.from('bike_models').select('*').order('name')]);if(p.error)toast(p.error.message);if(c.error)toast('ক্যাটাগরি টেবিল পাওয়া যায়নি। Supabase-এ dynamic-categories.sql চালান।');if(o.error)toast(o.error.message);if(i.error)console.warn('Order item report unavailable:',i.error.message);if(k.error)console.warn('Coupon table unavailable:',k.error.message);if(bm.error)console.warn('Bike models table unavailable. Run bike-models-migration.sql:',bm.error.message);products=p.data||[];categories=c.data||[];orders=o.data||[];orderItems=i.data||[];coupons=k.data||[];bikeModels=bm.data||[];renderBikeModelPickerOptions();renderStats();renderProducts();renderCategories();renderOrders();renderCustomers();renderReports();renderStockAlerts();renderCoupons();renderBikeModels();$('recent').innerHTML=orders.slice(0,5).map(orderLine).join('')||'<p>এখনো কোনো অর্ডার নেই</p>';$('productCategory').innerHTML='<option value="">ক্যাটাগরি নেই (Uncategorized)</option>'+categories.map(c=>'<option value="'+esc(c.name)+'">'+(c.parent_name?esc(c.parent_name)+' / ':'')+esc(c.name)+'</option>').join('');return ![p,c,o].some(x=>x.error)}function renderStats(){const pending=orders.filter(o=>o.status==='pending').length;$('sProducts').textContent=products.length.toLocaleString('bn-BD');$('sCategories').textContent=categories.length.toLocaleString('bn-BD');$('sOrders').textContent=orders.length.toLocaleString('bn-BD');$('sPending').textContent=pending.toLocaleString('bn-BD');$('sRevenue').textContent=money(orders.reduce((n,o)=>n+Number(o.total||0),0));$('pendingBadge').textContent=pending}function renderStockAlerts(){const low=products.filter(p=>Number(p.stock)<=5).sort((a,b)=>Number(a.stock)-Number(b.stock));$('stockAlerts').innerHTML=low.length?low.map(p=>'<div class="admin-row"><span><b>'+esc(p.name)+'</b><small>'+esc(p.category||'')+' · '+money(p.price)+'</small></span><i class="stock-alert '+(Number(p.stock)===0?'out':'low')+'">'+(Number(p.stock)===0?'স্টক শেষ':'স্টক '+Number(p.stock))+'</i></div>').join(''):'<p class="muted">সব পণ্যের স্টক পর্যাপ্ত আছে।</p>'}function reportOrdersForPeriod(){const period=$('reportPeriod')?.value||'30';const cutoff=period==='all'?0:Date.now()-Number(period)*86400000;return orders.filter(o=>{const time=new Date(o.created_at).getTime();return time>=cutoff&&['confirmed','shipped','delivered'].includes(o.status)})}function renderReports(){if(!$('reportSales'))return;const selected=reportOrdersForPeriod(),ids=new Set(selected.map(o=>String(o.id))),productSales=new Map();let sales=0,delivery=0;selected.forEach(o=>{sales+=Math.max(0,Number(o.total||0)-Number(o.delivery_fee||0));delivery+=Number(o.delivery_fee||0)});orderItems.filter(x=>ids.has(String(x.order_id))).forEach(x=>{const key=x.product_name;const row=productSales.get(key)||{name:key,qty:0,total:0};row.qty+=Number(x.quantity||0);row.total+=Number(x.unit_price||0)*Number(x.quantity||0);productSales.set(key,row)});$('reportSales').textContent=money(sales);$('reportOrders').textContent=selected.length.toLocaleString('bn-BD');$('reportAverage').textContent=money(selected.length?sales/selected.length:0);$('reportDelivery').textContent=money(delivery);const top=[...productSales.values()].sort((a,b)=>b.qty-a.qty).slice(0,10);$('topProducts').innerHTML=top.length?top.map((x,i)=>'<div class="admin-row"><span><b>'+(i+1)+'. '+esc(x.name)+'</b><small>'+x.qty.toLocaleString('bn-BD')+'টি বিক্রি</small></span><b>'+money(x.total)+'</b></div>').join(''):'<p class="muted">এই সময়ের মধ্যে কোনো বিক্রির তথ্য নেই।</p>'}function resetCouponForm(){const f=$('couponForm');f.reset();f.elements.id.value='';f.elements.max_uses.value='0';f.elements.active.checked=true;$('couponFormTitle').textContent='নতুন কুপন তৈরি';msg('couponMsg','')}
function splitBikeModels(value){return String(value||'').split(/[,/|;]+/).map(x=>x.trim()).filter(Boolean)}
let selectedBikeModels=[];
function renderBikeModelPickerOptions(){
 const list=$('bikeModelOptions'),search=($('bikeModelSearch')?.value||'').trim().toLocaleLowerCase();
 if(!list)return;
 const matches=bikeModels.filter(m=>m.name.toLocaleLowerCase().includes(search));
 list.innerHTML=matches.length?matches.map(m=>'<button type="button" class="bike-model-option '+(selectedBikeModels.some(x=>x.toLocaleLowerCase()===m.name.toLocaleLowerCase())?'selected':'')+'" data-bike-option="'+esc(m.id)+'"><span>'+esc(m.name)+'</span><b>'+(selectedBikeModels.some(x=>x.toLocaleLowerCase()===m.name.toLocaleLowerCase())?'✓':'＋')+'</b></button>').join(''):'<p class="bike-model-empty">কোনো মডেল পাওয়া যায়নি। Bike Models বিভাগ থেকে মডেল যোগ করুন।</p>';
}
function setSelectedBikeModels(names=[]){
 selectedBikeModels=[...new Map(names.map(x=>String(x).trim()).filter(Boolean).map(x=>[x.toLocaleLowerCase(),x])).values()];
 const hidden=$('productCompatibility');if(hidden)hidden.value=selectedBikeModels.join(', ');
 const chips=$('bikeModelSelected');
 if(chips)chips.innerHTML=selectedBikeModels.map(name=>'<span class="bike-model-chip">'+esc(name)+'<button type="button" data-bike-remove="'+esc(name)+'" aria-label="'+esc(name)+' বাদ দিন">×</button></span>').join('')||'<span class="bike-model-placeholder">কোনো মডেল নির্বাচন করা হয়নি</span>';
 renderBikeModelPickerOptions();
}
function toggleBikeModelPicker(force){
 const dropdown=$('bikeModelDropdown'),trigger=$('bikeModelTrigger');if(!dropdown||!trigger)return;
 const open=typeof force==='boolean'?force:dropdown.hidden;
 dropdown.hidden=!open;trigger.setAttribute('aria-expanded',String(open));
 if(open){$('bikeModelSearch').value='';renderBikeModelPickerOptions();$('bikeModelSearch').focus()}
}

function renderBikeModels(){const list=$('bikeModelsList');if(!list)return;$('bikeModelCount').textContent=bikeModels.length.toLocaleString('bn-BD');list.innerHTML=bikeModels.length?bikeModels.map(m=>'<div class="admin-row"><span><b>'+esc(m.name)+'</b></span><span class="actions"><button type="button" data-bike-edit="'+esc(m.id)+'">এডিট</button><button type="button" class="delete" data-bike-delete="'+esc(m.id)+'">ডিলিট</button></span></div>').join(''):'<p class="muted">কোনো Bike Model যোগ করা হয়নি।</p>';document.querySelectorAll('[data-bike-edit]').forEach(b=>b.onclick=()=>{const m=bikeModels.find(x=>String(x.id)===b.dataset.bikeEdit);if(!m)return;const f=$('bikeModelForm');f.elements.id.value=m.id;f.elements.name.value=m.name;$('bikeModelFormTitle').textContent='বাইক মডেল সম্পাদনা';msg('bikeModelMsg','')});document.querySelectorAll('[data-bike-delete]').forEach(b=>b.onclick=()=>deleteBikeModel(b.dataset.bikeDelete))}
function resetBikeModelForm(){const f=$('bikeModelForm');if(!f)return;f.reset();f.elements.id.value='';$('bikeModelFormTitle').textContent='নতুন বাইক মডেল';msg('bikeModelMsg','')}
async function saveBikeModel(e){e.preventDefault();const f=e.target,id=f.elements.id.value,name=f.elements.name.value.trim();if(!name)return;const duplicate=bikeModels.find(m=>m.name.toLocaleLowerCase()===name.toLocaleLowerCase()&&String(m.id)!==String(id));if(duplicate){msg('bikeModelMsg','এই মডেলটি আগে থেকেই আছে।');return}msg('bikeModelMsg','সেভ হচ্ছে...');if(!id){const {error}=await db.from('bike_models').insert({name});if(error){msg('bikeModelMsg','সেভ হয়নি: '+error.message);return}}else{const old=bikeModels.find(m=>String(m.id)===String(id));if(!old)return;const affected=products.filter(p=>splitBikeModels(p.compatibility).some(x=>x.toLocaleLowerCase()===old.name.toLocaleLowerCase()));for(const p of affected){const updated=splitBikeModels(p.compatibility).map(x=>x.toLocaleLowerCase()===old.name.toLocaleLowerCase()?name:x);const {error}=await db.from('products').update({compatibility:[...new Set(updated)].join(', ')}).eq('id',p.id);if(error){msg('bikeModelMsg','পণ্যের Compatibility আপডেট হয়নি: '+error.message+'। মডেলের নাম পরিবর্তন করা হয়নি।');await refresh();return}}const {error}=await db.from('bike_models').update({name}).eq('id',id);if(error){msg('bikeModelMsg','মডেল আপডেট হয়নি: '+error.message);await refresh();return}}resetBikeModelForm();await refresh();page('bike-models');toast('Bike Model সেভ হয়েছে')}
async function deleteBikeModel(id){const model=bikeModels.find(m=>String(m.id)===String(id));if(!model||!confirm('"'+model.name+'" মুছে ফেলবেন? পণ্যের অন্য তথ্য ও অন্য মডেল অক্ষত থাকবে; শুধু এই Compatibility নামটি সরানো হবে।'))return;for(const p of products.filter(p=>splitBikeModels(p.compatibility).some(x=>x.toLocaleLowerCase()===model.name.toLocaleLowerCase()))){const remaining=splitBikeModels(p.compatibility).filter(x=>x.toLocaleLowerCase()!==model.name.toLocaleLowerCase());const {error}=await db.from('products').update({compatibility:remaining.join(', ')}).eq('id',p.id);if(error){toast('পণ্যের Compatibility আপডেট হয়নি: '+error.message);await refresh();return}}const {error}=await db.from('bike_models').delete().eq('id',id);if(error){toast('মডেল ডিলিট হয়নি: '+error.message);await refresh();return}await refresh();toast('Bike Model মুছে ফেলা হয়েছে')}
function renderCoupons(){if(!$('couponsList'))return;$('couponsList').innerHTML=coupons.length?coupons.map(c=>'<div class="admin-row coupon-row"><span><b>'+esc(c.code)+'</b><small>ছাড় '+money(c.discount_amount)+' · ব্যবহার '+Number(c.used_count||0)+'/'+(c.max_uses==null?'সীমাহীন':Number(c.max_uses))+'</small></span><span class="actions"><i class="coupon-state '+(c.active?'on':'off')+'">'+(c.active?'চালু':'বন্ধ')+'</i><button data-coupon-edit="'+esc(c.id)+'">এডিট</button><button data-coupon-toggle="'+esc(c.id)+'">'+(c.active?'বন্ধ':'চালু')+'</button><button class="delete" data-coupon-delete="'+esc(c.id)+'">ডিলিট</button></span></div>').join(''):'<p class="muted">এখনো কোনো কুপন তৈরি করা হয়নি।</p>';document.querySelectorAll('[data-coupon-edit]').forEach(b=>b.onclick=()=>{const c=coupons.find(x=>String(x.id)===b.dataset.couponEdit);if(!c)return;const f=$('couponForm');f.elements.id.value=c.id;f.elements.code.value=c.code;f.elements.discount_amount.value=c.discount_amount;f.elements.max_uses.value=c.max_uses??0;f.elements.active.checked=!!c.active;$('couponFormTitle').textContent='কুপন সম্পাদনা';page('coupons');f.scrollIntoView({behavior:'smooth',block:'center'})});document.querySelectorAll('[data-coupon-toggle]').forEach(b=>b.onclick=async()=>{const c=coupons.find(x=>String(x.id)===b.dataset.couponToggle);if(!c)return;const {error}=await db.from('coupons').update({active:!c.active}).eq('id',c.id);if(error){toast(error.message);return}await refresh();toast('কুপনের অবস্থা আপডেট হয়েছে')});document.querySelectorAll('[data-coupon-delete]').forEach(b=>b.onclick=async()=>{const c=coupons.find(x=>String(x.id)===b.dataset.couponDelete);if(!c||!confirm('এই কুপনটি ডিলিট করবেন?'))return;const {error}=await db.from('coupons').delete().eq('id',c.id);if(error){toast(error.message);return}await refresh();resetCouponForm();toast('কুপন ডিলিট হয়েছে')})}
async function saveCoupon(e){e.preventDefault();const f=e.target,code=f.elements.code.value.trim().toUpperCase(),discount=Number(f.elements.discount_amount.value),maxRaw=Number(f.elements.max_uses.value||0);if(!code){msg('couponMsg','কুপন কোড লিখুন।');return}if(!Number.isInteger(discount)||discount<1){msg('couponMsg','ছাড়ের পরিমাণ কমপক্ষে ১ টাকা হতে হবে।');return}if(!Number.isInteger(maxRaw)||maxRaw<0){msg('couponMsg','ব্যবহার সংখ্যা ০ অথবা তার বেশি পূর্ণসংখ্যা দিন।');return}const row={code,discount_amount:discount,max_uses:maxRaw===0?null:maxRaw,active:f.elements.active.checked};const q=f.elements.id.value?db.from('coupons').update(row).eq('id',f.elements.id.value):db.from('coupons').insert(row);const {error}=await q;if(error){msg('couponMsg',error.message);return}resetCouponForm();await refresh();toast('কুপন সফলভাবে সেভ হয়েছে')}
function exportReportCSV(){const selected=reportOrdersForPeriod();const rows=[['Order ID','Date','Customer','Phone','Status','Product subtotal','Delivery fee','Total'],...selected.map(o=>[o.id,o.created_at,o.customer_name,o.phone,o.status,Math.max(0,Number(o.total||0)-Number(o.delivery_fee||0)),Number(o.delivery_fee||0),Number(o.total||0)])];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='parts-market-sales-report.csv';a.click();URL.revokeObjectURL(url)}function renderProducts(){const term=($('productSearch').value||'').toLowerCase();$('productsList').innerHTML=products.filter(p=>(p.name+' '+p.category+' '+(p.compatibility||'')).toLowerCase().includes(term)).map(p=>'<div class="admin-row"><span><b>'+esc(p.name)+'</b><small>'+esc(p.category)+' · '+money(p.price)+' · বাইক: '+esc(p.compatibility||'সব')+' · '+(Number(p.stock)>0?'স্টক '+Number(p.stock):'স্টক আউট')+'</small></span><span class="actions"><button data-stock-dec="'+p.id+'" '+(Number(p.stock)<=0?'disabled':'')+'>−</button><button data-stock-inc="'+p.id+'">+</button><button data-edit="'+p.id+'">এডিট</button><button class="delete" data-delete="'+p.id+'">ডিলিট</button></span></div>').join('')||'<p>কোনো পণ্য নেই</p>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProduct(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.delete));document.querySelectorAll('[data-stock-inc],[data-stock-dec]').forEach(b=>b.onclick=()=>adjustStock(b.dataset.stockInc||b.dataset.stockDec,b.hasAttribute('data-stock-inc')?1:-1))}async function adjustStock(id,delta){const p=products.find(x=>String(x.id)===String(id));if(!p)return;const next=Math.max(0,Number(p.stock||0)+delta);const {error}=await db.from('products').update({stock:next}).eq('id',id);if(error)return msg('productMsg','স্টক আপডেট হয়নি: '+error.message);p.stock=next;renderProducts();renderStockAlerts();}
function renderCategoryParentOptions(selected='',exclude=''){const s=$('categoryParent');if(!s)return;s.innerHTML='<option value="">মূল ক্যাটাগরি (Parent)</option>'+categories.filter(c=>!c.parent_name&&c.name!==exclude).map(c=>'<option value="'+esc(c.name)+'">'+esc(c.name)+'</option>').join('');s.value=selected||''}
function renderCategories(){$('categoryCount').textContent=categories.length.toLocaleString('bn-BD');const roots=categories.filter(c=>!c.parent_name);$('categoriesList').innerHTML=roots.map(c=>{const children=categories.filter(x=>x.parent_name===c.name);const row=x=>'<div class="admin-row"><b>'+esc(x.name)+(x.parent_name?' <small>— '+esc(x.parent_name)+'</small>':'')+'</b><span class="actions"><button data-cat-edit="'+esc(x.name)+'">এডিট</button><button class="delete" data-cat-delete="'+esc(x.name)+'">ডিলিট</button></span></div>';return row(c)+children.map(row).join('')}).join('')||'<p>কোনো ক্যাটাগরি নেই</p>';renderCategoryParentOptions();document.querySelectorAll('[data-cat-edit]').forEach(b=>b.onclick=()=>{const c=categories.find(x=>x.name===b.dataset.catEdit);$('categoryForm').elements.old.value=c.name;$('categoryForm').elements.name.value=c.name;renderCategoryParentOptions(c.parent_name||'',c.name);$('categoryHeading').textContent='ক্যাটাগরি এডিট'});document.querySelectorAll('[data-cat-delete]').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.catDelete))}
async function saveCategory(e){e.preventDefault();const f=e.target,old=f.elements.old.value.trim(),name=f.elements.name.value.trim(),parent_name=f.elements.parent_name.value||null;if(!name)return msg('categoryMsg','ক্যাটাগরির নাম লিখুন');if(parent_name===name)return msg('categoryMsg','ক্যাটাগরি নিজেই নিজের Sub-catalogue হতে পারে না।');msg('categoryMsg','সেভ হচ্ছে...');if(old){const count=await db.from('products').select('id',{count:'exact',head:true}).eq('category',old);if(count.error)return msg('categoryMsg',count.error.message);let r=await db.from('categories').update({name,parent_name}).eq('name',old);if(r.error)return msg('categoryMsg',r.error.message);if(old!==name&&count.count){r=await db.from('products').update({category:name}).eq('category',old);if(r.error)return msg('categoryMsg','ক্যাটাগরি বদলেছে, পণ্য আপডেট হয়নি: '+r.error.message)}}else{const r=await db.from('categories').insert({name,parent_name});if(r.error)return msg('categoryMsg',r.error.message)}f.reset();f.elements.old.value='';$('categoryHeading').textContent='নতুন ক্যাটাগরি';renderCategoryParentOptions();msg('categoryMsg','সফলভাবে সেভ হয়েছে');await refresh()}
async function deleteCategory(name){
 const childResult=await db.from('categories').select('name').eq('parent_name',name);
 if(childResult.error)return toast(childResult.error.message);
 const childNames=(childResult.data||[]).map(c=>c.name),names=[name,...childNames];
 const message=childNames.length?name+' এবং এর '+childNames.length+'টি Sub-category মুছবেন? সংশ্লিষ্ট পণ্য Uncategorized হবে; কোনো পণ্য ডিলিট হবে না।':name+' ক্যাটাগরি মুছবেন? সংশ্লিষ্ট পণ্য Uncategorized হবে; কোনো পণ্য ডিলিট হবে না।';
 if(!confirm(message))return;
 const moved=await db.from('products').update({category:''}).in('category',names);
 if(moved.error)return toast('পণ্যের ক্যাটাগরি খালি করা যায়নি: '+moved.error.message);
 if(childNames.length){const dc=await db.from('categories').delete().in('name',childNames);if(dc.error)return toast('পণ্য Uncategorized হয়েছে, কিন্তু Sub-category মুছতে সমস্যা: '+dc.error.message)}
 const deleted=await db.from('categories').delete().eq('name',name);
 if(deleted.error)return toast('পণ্য Uncategorized হয়েছে, কিন্তু ক্যাটাগরি মুছতে সমস্যা: '+deleted.error.message);
 await refresh();toast('ক্যাটাগরি মুছে ফেলা হয়েছে। পণ্য All Products-এ থাকবে।')
}
