function addVariantRow(v={}){const list=$('variantsList');if(!list)return;const row=document.createElement('div');row.className='variant-editor-row';row.dataset.images=JSON.stringify(Array.isArray(v.images)?v.images:[]);row.innerHTML='<div class="variant-editor-fields"><label>Colour Name<input class="variant-name" required maxlength="40" placeholder="যেমন: Red" value="'+esc(v.name||'')+'"></label><label>দাম (৳) <small>ঐচ্ছিক</small><input class="variant-price" type="number" min="0" step="1" value="'+(v.price??'')+'" placeholder="খালি রাখলে মূল দাম"></label><label>স্টক <small>ঐচ্ছিক</small><input class="variant-stock" type="number" min="0" step="1" value="'+(v.stock??'')+'" placeholder="খালি রাখলে মূল স্টক"></label></div><label class="variant-image-label">এই Colour-এর ছবি (একাধিক নির্বাচন করা যাবে)<input class="variant-image-files" type="file" accept="image/*" multiple></label><div class="variant-selected-preview"></div><div class="variant-existing-images"></div><button type="button" class="variant-remove">এই Colour বাদ দিন</button>';const preview=row.querySelector('.variant-existing-images');const images=Array.isArray(v.images)?v.images:[];preview.innerHTML=images.map((url,i)=>'<div class="variant-existing-item"><img src="'+esc(url)+'" alt="বর্তমান Colour ছবি"><small>আগের ছবি</small><button type="button" data-edit-variant-existing="'+esc(url)+'" data-photo-index="'+i+'">Edit</button></div>').join('')+(images.length?'<small>আগের ছবি সংরক্ষিত থাকবে।</small>':'');row.querySelector('.variant-remove').onclick=()=>row.remove();list.appendChild(row);bindVariantPhotoEditors(row)}
async function prepareProductImage(file){
  const type=file.type||'';
  if(!type.startsWith('image/'))throw new Error('শুধু JPG, PNG অথবা WebP ছবির ফাইল নির্বাচন করুন।');
  let source=null,bitmap=null,objectUrl=null;
  try{
    if(typeof createImageBitmap==='function'){
      try{bitmap=await createImageBitmap(file);source=bitmap}catch(_){}
    }
    if(!source){
      objectUrl=URL.createObjectURL(file);
      source=await new Promise((resolve,reject)=>{
        const img=new Image();
        img.onload=()=>resolve(img);
        img.onerror=()=>reject(new Error('ছবিটি খোলা যাচ্ছে না। অন্য ছবি নির্বাচন করুন।'));
        img.src=objectUrl;
      });
    }
    const width=source.width||source.naturalWidth,height=source.height||source.naturalHeight;
    if(!width||!height)throw new Error('ছবির সাইজ পড়া যাচ্ছে না।');
    const scale=Math.min(1,1600/Math.max(width,height));
    const canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(width*scale));
    canvas.height=Math.max(1,Math.round(height*scale));
    const ctx=canvas.getContext('2d');
    if(!ctx)throw new Error('ছবি প্রসেস করার সুবিধা পাওয়া যাচ্ছে না।');
    ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.drawImage(source,0,0,canvas.width,canvas.height);
    const blob=await new Promise((resolve,reject)=>{
      if(typeof canvas.toBlob==='function'){
        canvas.toBlob(result=>result?resolve(result):reject(new Error('ছবি কমপ্রেস করা যায়নি।')),'image/jpeg',0.82);
      }else{
        try{
          const dataUrl=canvas.toDataURL('image/jpeg',0.82);
          const binary=atob(dataUrl.split(',')[1]),bytes=new Uint8Array(binary.length);
          for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
          resolve(new Blob([bytes],{type:'image/jpeg'}));
        }catch(err){reject(err)}
      }
    });
    return{blob,ext:'jpg',contentType:'image/jpeg'};
  }catch(err){
    if(file.size<=5*1024*1024&&type.startsWith('image/')){
      const ext=type==='image/png'?'png':type==='image/webp'?'webp':type==='image/gif'?'gif':'jpg';
      return{blob:file,ext,contentType:type};
    }
    throw new Error(err.message||'ছবিটি প্রসেস করা যাচ্ছে না। JPG/PNG/WebP ছবি ব্যবহার করুন।');
  }finally{
    bitmap?.close?.();
    if(objectUrl)URL.revokeObjectURL(objectUrl);
  }
}async function uploadVariantImage(file){if(!file.type.startsWith('image/'))throw new Error('শুধু ছবির ফাইল নির্বাচন করুন।');const prepared=await prepareProductImage(file),path='variants/'+crypto.randomUUID()+'.'+prepared.ext;const up=await db.storage.from('product-images').upload(path,prepared.blob,{upsert:false,contentType:prepared.contentType});if(up.error)throw up.error;return db.storage.from('product-images').getPublicUrl(path).data.publicUrl}
function clearGallerySelection(){selectedGalleryFiles.forEach(x=>{if(x.preview)URL.revokeObjectURL(x.preview)});selectedGalleryFiles=[];const picker=$('galleryPicker');if(picker)picker.value='';renderGalleryPreview()}function renderGalleryPreview(){const preview=$('galleryPreview');preview.innerHTML=selectedGalleryFiles.map((x,i)=>'<div class="gallery-thumb"><img src="'+x.preview+'" alt="নির্বাচিত ছবি"><button type="button" data-gallery-edit="'+i+'">✎ Edit</button><button type="button" data-gallery-remove="'+i+'">✕ বাদ দিন</button></div>').join('');const count=selectedGalleryFiles.length;const note=$('gallerySelectionCount');if(note)note.textContent=count?count.toLocaleString('bn-BD')+'টি ছবি নির্বাচিত':'এখনো কোনো ছবি নির্বাচন করা হয়নি';document.querySelectorAll('[data-gallery-remove]').forEach(b=>b.onclick=()=>{const item=selectedGalleryFiles.splice(Number(b.dataset.galleryRemove),1)[0];if(item?.preview)URL.revokeObjectURL(item.preview);renderGalleryPreview()});document.querySelectorAll('[data-gallery-edit]').forEach(b=>b.onclick=()=>attachGalleryEditor(selectedGalleryFiles[Number(b.dataset.galleryEdit)].file,Number(b.dataset.galleryEdit)))}async function uploadImagesWithLimit(files,limit=3){const results=new Array(files.length);let next=0;async function worker(){while(next<files.length){const index=next++;results[index]=await uploadVariantImage(files[index])}}await Promise.all(Array.from({length:Math.min(limit,files.length)},()=>worker()));return results}function editProduct(id){const p=products.find(x=>String(x.id)===String(id)),f=$('productForm');clearGallerySelection();f.elements.image.value='';for(const k of ['id','name','price','stock','category','description'])f.elements[k].value=p[k]??'';setSelectedBikeModels(splitBikeModels(p.compatibility));f.dataset.existingImages=JSON.stringify(Array.isArray(p.images)?p.images:[]);f.dataset.oldMainImageUrl=p.image_url||'';pendingImageReplacements.clear();replacedStorageUrls.clear();$('mainImageEditor').textContent='';renderExistingProductImages(p);clearVariantEditor();const variants=Array.isArray(p.variants)&&p.variants.length?p.variants:(Array.isArray(p.colors)?p.colors.map(name=>({name,price:p.price,stock:p.stock,images:[]})):[]);variants.forEach(v=>addVariantRow(v));$('productFormTitle').textContent='পণ্য সম্পাদনা';f.hidden=false;page('products');f.scrollIntoView({behavior:'smooth'})}

