function photoEditorRotate(degrees){if(!photoEditorCropImage||!photoEditorCropCanvas)return;const old=photoEditorCropImage,w=old.width,h=old.height,tmp=document.createElement('canvas'),swap=Math.abs(degrees)%180===90;tmp.width=swap?h:w;tmp.height=swap?w:h;const ctx=tmp.getContext('2d');ctx.translate(tmp.width/2,tmp.height/2);ctx.rotate(degrees*Math.PI/180);ctx.drawImage(old,-w/2,-h/2);photoEditorCropImage=tmp;photoEditorCropCanvas.width=tmp.width;photoEditorCropCanvas.height=tmp.height;photoEditorCropRect={x:0,y:0,w:tmp.width,h:tmp.height};photoEditorDrawCropStage()}
