function drawPhotoEditorCanvas(){if(!photoEditorCanvas||!photoEditorContext)return;const c=photoEditorCanvas,ctx=photoEditorContext;ctx.clearRect(0,0,c.width,c.height);ctx.filter='brightness('+photoEditorBrightness+'%) contrast('+photoEditorContrast+'%)';ctx.drawImage(c._source,0,0,c.width,c.height);ctx.filter='none';photoEditorTexts.forEach((t,i)=>{const size=Math.max(12,Math.round(t.size*c.width/1000));ctx.font=(t.bold?'bold ':'')+size+'px Arial,sans-serif';ctx.textBaseline='middle';ctx.lineWidth=Math.max(2,size*.09);ctx.strokeStyle='rgba(0,0,0,.6)';ctx.fillStyle=t.color;const x=t.x*c.width,y=t.y*c.height;ctx.strokeText(t.text,x,y);ctx.fillText(t.text,x,y);if(i===photoEditorSelectedText){ctx.strokeStyle='#ff5364';ctx.lineWidth=2;ctx.setLineDash([6,4]);ctx.strokeRect(x-5,y-size*.7,ctx.measureText(t.text).width+10,size*1.4);ctx.setLineDash([])}})}
function photoEditorPoint(e){const r=photoEditorCanvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*photoEditorCanvas.width,y:(e.clientY-r.top)/r.height*photoEditorCanvas.height}}
function bindPhotoEditorCanvas(){photoEditorCanvas.onpointerdown=e=>{const p=photoEditorPoint(e);let hit=-1;for(let i=photoEditorTexts.length-1;i>=0;i--){const t=photoEditorTexts[i],size=Math.max(12,Math.round(t.size*photoEditorCanvas.width/1000));photoEditorContext.font=(t.bold?'bold ':'')+size+'px Arial,sans-serif';const w=photoEditorContext.measureText(t.text).width;if(p.x>=t.x*photoEditorCanvas.width-8&&p.x<=t.x*photoEditorCanvas.width+w+8&&p.y>=t.y*photoEditorCanvas.height-size&&p.y<=t.y*photoEditorCanvas.height+size){hit=i;break}}photoEditorSelectedText=hit;if(hit>=0){const selected=photoEditorTexts[hit];$('photoEditorText').value=selected.text;$('photoEditorTextColor').value=selected.color;$('photoEditorTextSize').value=selected.size;$('photoEditorBold').checked=selected.bold;photoEditorDrag={x:p.x,y:p.y,tx:photoEditorTexts[hit].x,ty:photoEditorTexts[hit].y};photoEditorCanvas.setPointerCapture(e.pointerId)}drawPhotoEditorCanvas()};photoEditorCanvas.onpointermove=e=>{if(!photoEditorDrag)return;const p=photoEditorPoint(e),t=photoEditorTexts[photoEditorSelectedText];t.x=Math.max(0,Math.min(1,photoEditorDrag.tx+(p.x-photoEditorDrag.x)/photoEditorCanvas.width));t.y=Math.max(0,Math.min(1,photoEditorDrag.ty+(p.y-photoEditorDrag.y)/photoEditorCanvas.height));drawPhotoEditorCanvas()};photoEditorCanvas.onpointerup=()=>photoEditorDrag=null;photoEditorCanvas.onpointercancel=()=>photoEditorDrag=null}
$('photoEditorClose').onclick=closePhotoEditor;$('photoEditorModal').addEventListener('click',e=>{if(e.target===$('photoEditorModal'))closePhotoEditor()});$('photoEditorRotateLeft').onclick=()=>photoEditorRotate(-90);$('photoEditorRotateRight').onclick=()=>photoEditorRotate(90);
$('photoEditorApplyCrop').onclick=()=>{if(!photoEditorCropImage||!photoEditorCropRect)return;const r=photoEditorCropRect,c=document.createElement('canvas');c.width=Math.max(1,Math.round(r.w));c.height=Math.max(1,Math.round(r.h));c.getContext('2d').drawImage(photoEditorCropImage,r.x,r.y,r.w,r.h,0,0,c.width,c.height);photoEditorCanvas=$('photoEditorCanvas');photoEditorCanvas.width=c.width;photoEditorCanvas.height=c.height;photoEditorContext=photoEditorCanvas.getContext('2d');photoEditorCanvas._source=c;$('photoEditorCropWrap').hidden=true;$('photoEditorCanvasWrap').hidden=false;$('photoEditorCropActions').hidden=true;$('photoEditorSave').disabled=false;bindPhotoEditorCanvas();drawPhotoEditorCanvas();$('photoEditorMessage').textContent='Text লিখে ＋ Text যোগ চাপুন। ছবির ওপর Text টেনে সরাতে পারবেন。'};
$('photoEditorBrightness').oninput=e=>{photoEditorBrightness=Number(e.target.value);drawPhotoEditorCanvas()};$('photoEditorContrast').oninput=e=>{photoEditorContrast=Number(e.target.value);drawPhotoEditorCanvas()};
$('photoEditorText').oninput=e=>{if(photoEditorSelectedText>=0){photoEditorTexts[photoEditorSelectedText].text=e.target.value;drawPhotoEditorCanvas()}};$('photoEditorTextColor').oninput=e=>{if(photoEditorSelectedText>=0){photoEditorTexts[photoEditorSelectedText].color=e.target.value;drawPhotoEditorCanvas()}};$('photoEditorTextSize').oninput=e=>{if(photoEditorSelectedText>=0){photoEditorTexts[photoEditorSelectedText].size=Number(e.target.value);drawPhotoEditorCanvas()}};$('photoEditorBold').onchange=e=>{if(photoEditorSelectedText>=0){photoEditorTexts[photoEditorSelectedText].bold=e.target.checked;drawPhotoEditorCanvas()}};
$('photoEditorAddText').onclick=()=>{const value=$('photoEditorText').value.trim();if(!value||!photoEditorCanvas){toast('আগে Crop Apply করুন, তারপর Text যোগ করুন।');return}photoEditorTexts.push({text:value,color:$('photoEditorTextColor').value,size:Number($('photoEditorTextSize').value)||5,bold:$('photoEditorBold').checked,x:.5,y:.5});photoEditorSelectedText=photoEditorTexts.length-1;drawPhotoEditorCanvas()};$('photoEditorDeleteText').onclick=()=>{if(photoEditorSelectedText<0)return;photoEditorTexts.splice(photoEditorSelectedText,1);photoEditorSelectedText=-1;drawPhotoEditorCanvas()};
$('photoEditorSave').onclick=async()=>{if(!photoEditorCanvas||!photoEditorFileCallback)return;try{$('photoEditorSave').disabled=true;$('photoEditorMessage').textContent='ছবি প্রস্তুত হচ্ছে...';const out=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(photoEditorCanvas.width,photoEditorCanvas.height));out.width=Math.max(1,Math.round(photoEditorCanvas.width*scale));out.height=Math.max(1,Math.round(photoEditorCanvas.height*scale));const ctx=out.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(photoEditorCanvas,0,0,out.width,out.height);const blob=await new Promise((resolve,reject)=>out.toBlob(b=>b?resolve(b):reject(new Error('ছবি তৈরি করা যায়নি。')),'image/jpeg',.86));const file=new File([blob],'edited-'+Date.now()+'.jpg',{type:'image/jpeg'}),callback=photoEditorFileCallback;closePhotoEditor();callback(file)}catch(err){$('photoEditorMessage').textContent='সমস্যা: '+err.message;$('photoEditorSave').disabled=false}};
function attachGalleryEditor(file,index){openPhotoEditor(file,edited=>{const old=selectedGalleryFiles[index];if(old?.preview)URL.revokeObjectURL(old.preview);selectedGalleryFiles[index]={file:edited,preview:URL.createObjectURL(edited)};renderGalleryPreview()})}
function renderExistingProductImages(p){const el=$('currentProductImages'),items=[];if(p.image_url)items.push({kind:'main',url:p.image_url,label:'প্রধান ছবি'});(Array.isArray(p.images)?p.images:[]).forEach((url,i)=>items.push({kind:'gallery',index:i,url,label:'অতিরিক্ত ছবি '+(i+1)}));el.innerHTML=items.length?'<div class="existing-photo-grid">'+items.map(x=>'<div class="existing-photo-card"><img src="'+esc(x.url)+'" alt="'+esc(x.label)+'"><small>'+esc(x.label)+'</small><button type="button" data-existing-photo="'+x.kind+'" data-photo-index="'+(x.index??'')+'" data-photo-url="'+esc(x.url)+'">Edit</button></div>').join('')+'</div>':'এখনো কোনো ছবি নেই'}
$('currentProductImages').addEventListener('click',e=>{const b=e.target.closest('[data-existing-photo]');if(!b)return;const url=b.dataset.photoUrl,kind=b.dataset.existingPhoto,index=Number(b.dataset.photoIndex);openExistingPhotoEditor(url,edited=>{if(kind==='main'){replaceInputFile($('productForm').elements.image,edited)}else{pendingImageReplacements.set(url,edited);replacedStorageUrls.add(url);const arr=JSON.parse($('productForm').dataset.existingImages||'[]');arr[index]='__REPLACED__:'+url;$('productForm').dataset.existingImages=JSON.stringify(arr);b.closest('.existing-photo-card').querySelector('small').textContent='এডিট করা ছবি প্রস্তুত'}})});
