function bindVariantPhotoEditors(row){const input=row.querySelector('.variant-image-files'),preview=row.querySelector('.variant-selected-preview');const render=()=>{preview.innerHTML=Array.from(input.files||[]).map((f,i)=>'<span>'+esc(f.name)+' <button type="button" data-edit-variant-new="'+i+'">Edit</button></span>').join('')};input.addEventListener('change',render);preview.addEventListener('click',e=>{const b=e.target.closest('[data-edit-variant-new]');if(!b)return;const i=Number(b.dataset.editVariantNew),files=Array.from(input.files);openPhotoEditor(files[i],edited=>{files[i]=edited;const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));input.files=dt.files;render()})})}
$('variantsList').addEventListener('click',e=>{const b=e.target.closest('[data-edit-variant-existing]');if(!b)return;const url=b.dataset.editVariantExisting;openExistingPhotoEditor(url,edited=>{pendingImageReplacements.set(url,edited);replacedStorageUrls.add(url);const row=b.closest('.variant-editor-row'),images=JSON.parse(row.dataset.images||'[]');images[Number(b.dataset.photoIndex)]='__REPLACED__:'+url;row.dataset.images=JSON.stringify(images);b.closest('.variant-existing-item').querySelector('small').textContent='এডিট করা ছবি প্রস্তুত'})});

async function saveProduct(e){e.preventDefault();const f=e.target,d=new FormData(f),id=d.get('id'),basePrice=Number(d.get('price')),baseStock=Number(d.get('stock'));msg('productMsg','ছবি ও পণ্যের তথ্য সেভ হচ্ছে...');try{if(!Number.isFinite(basePrice)||basePrice<0||!Number.isInteger(baseStock)||baseStock<0)throw new Error('মূল পণ্যের সঠিক দাম ও স্টক লিখুন।');let image_url=null;let existingImages=JSON.parse(f.dataset.existingImages||'[]');const mainFile=f.elements.image.files[0];if(mainFile){const prepared=await prepareProductImage(mainFile),path=crypto.randomUUID()+'.'+prepared.ext;const up=await db.storage.from('product-images').upload(path,prepared.blob,{upsert:false,contentType:prepared.contentType});if(up.error)throw up.error;image_url=db.storage.from('product-images').getPublicUrl(path).data.publicUrl}const usedReplacementUrls=new Set(existingImages.filter(url=>String(url).startsWith('__REPLACED__:')).map(url=>String(url).slice(13)));document.querySelectorAll('.variant-editor-row').forEach(vr=>JSON.parse(vr.dataset.images||'[]').forEach(url=>{if(String(url).startsWith('__REPLACED__:'))usedReplacementUrls.add(String(url).slice(13))}));replacedStorageUrls=new Set(usedReplacementUrls);if(mainFile&&f.dataset.oldMainImageUrl)replacedStorageUrls.add(f.dataset.oldMainImageUrl);const replacementUrls=new Map();for(const [oldUrl,file] of pendingImageReplacements){if(!usedReplacementUrls.has(oldUrl))continue;const newUrl=await uploadVariantImage(file);replacementUrls.set(oldUrl,newUrl)}existingImages=existingImages.map(url=>String(url).startsWith('__REPLACED__:')?(replacementUrls.get(String(url).slice(13))||url):url);const galleryFiles=selectedGalleryFiles.map(x=>x.file),newImages=await uploadImagesWithLimit(galleryFiles,3);const variants=[];for(const row of document.querySelectorAll('.variant-editor-row')){const name=row.querySelector('.variant-name').value.trim(),priceRaw=row.querySelector('.variant-price').value.trim(),stockRaw=row.querySelector('.variant-stock').value.trim(),price=priceRaw===''?basePrice:Number(priceRaw),stock=stockRaw===''?baseStock:Number(stockRaw);if(!name||!Number.isFinite(price)||price<0||!Number.isInteger(stock)||stock<0)throw new Error('প্রতিটি Colour-এর নাম দিন; দাম ও স্টক দিলে সঠিক সংখ্যা লিখুন।');const images=JSON.parse(row.dataset.images||'[]').map(url=>String(url).startsWith('__REPLACED__:')?(replacementUrls.get(String(url).slice(13))||url):url);for(const file of row.querySelector('.variant-image-files').files)images.push(await uploadVariantImage(file));variants.push({name,price,stock,images:[...new Set(images)]})}if(new Set(variants.map(v=>v.name.toLocaleLowerCase())).size!==variants.length)throw new Error('একই Colour একাধিকবার যোগ করা যাবে না।');const row={name:d.get('name').trim(),price:variants.length?Math.min(...variants.map(v=>v.price)):basePrice,stock:variants.length?variants.reduce((n,v)=>n+v.stock,0):baseStock,category:d.get('category'),compatibility:selectedBikeModels.join(', '),description:d.get('description'),colors:variants.map(v=>v.name),variants,images:[...existingImages,...newImages],active:true};if(image_url)row.image_url=image_url;const r=id?await db.from('products').update(row).eq('id',id):await db.from('products').insert(row);if(r.error)throw r.error;if(replacedStorageUrls.size){const paths=[...replacedStorageUrls].map(url=>{try{const u=new URL(url),marker='/storage/v1/object/public/product-images/',i=u.pathname.indexOf(marker);return i>=0?decodeURIComponent(u.pathname.slice(i+marker.length)):null}catch{return null}}).filter(Boolean);if(paths.length){const removed=await db.storage.from('product-images').remove([...new Set(paths)]);if(removed.error)toast('পণ্য সেভ হয়েছে, তবে পুরোনো কিছু ছবি Storage থেকে মুছতে পারেনি: '+removed.error.message)}}pendingImageReplacements.clear();replacedStorageUrls.clear();f.reset();$('mainImageEditor').textContent='';setSelectedBikeModels([]);clearGallerySelection();clearVariantEditor();f.dataset.existingImages='[]';$('currentProductImages').textContent='';f.hidden=true;msg('productMsg','');await refresh();toast('পণ্য সেভ হয়েছে')}catch(err){msg('productMsg','সেভ হয়নি: '+(err.message||String(err)))}}
async function deleteProduct(id){if(!confirm('এই পণ্যটি মুছবেন?'))return;const r=await db.from('products').delete().eq('id',id);if(r.error)return toast(r.error.message);await refresh()}function orderLine(o){return '<div class="admin-row"><span><b>#'+esc(o.id)+' · '+esc(o.customer_name)+'</b><small>'+esc(o.phone)+' · '+money(o.total)+'</small></span><i class="status '+esc(o.status)+'">'+esc(o.status)+'</i></div>'}async function callSteadfast(action,id,button){
if(action==='book'&&!confirm('এই অর্ডারটি এখন Steadfast-এ বুক করবেন? এটি বাস্তব কুরিয়ার বুকিং তৈরি করবে।'))return;
const original=button.textContent;button.disabled=true;button.textContent=action==='book'?'Steadfast-এ বুক হচ্ছে...':'স্ট্যাটাস আনা হচ্ছে...';
try{
const {data,error}=await db.functions.invoke('Steadfast_integration',{body:{action,order_id:id}});
if(error){let detail=error.message||'Function request failed';try{const body=await error.context.json();detail=body.error||body.message||detail}catch{}throw new Error(detail)}
if(!data?.success)throw new Error(data?.error||'Steadfast request failed');
toast(action==='book'?'Steadfast বুকিং সফল হয়েছে। Consignment ID: '+data.consignment_id:'Steadfast স্ট্যাটাস আপডেট হয়েছে: '+data.delivery_status);
await refresh();
}catch(err){button.disabled=false;button.textContent=original;toast('Steadfast সমস্যা: '+(err.message||String(err)))}
}
function renderOrders(){const list=filter==='all'?orders:orders.filter(o=>o.status===filter);$('ordersList').innerHTML=list.map(o=>'<div class="order-row"><div><b>#'+esc(o.id)+' · '+esc(o.customer_name)+'</b><small>'+esc(o.phone)+' · '+new Date(o.created_at).toLocaleString('bn-BD')+'</small><small>'+esc(o.address)+'</small><small>'+((Number(o.discount_amount||0)>0)?'কুপন: '+esc(o.coupon_code||'')+' · ছাড় '+money(o.discount_amount):'কুপন ব্যবহার হয়নি')+'</small><button class="link" data-detail="'+o.id+'">পণ্যের বিস্তারিত</button><div id="detail-'+o.id+'"></div><div class="courier-editor" style="margin-top:10px;padding:10px;border:1px solid #ddd;border-radius:8px"><b>Steadfast কুরিয়ার ট্র্যাকিং</b><input data-consignment="'+esc(o.id)+'" placeholder="Consignment ID" value="'+esc(o.consignment_id||'')+'" style="display:block;width:100%;margin:6px 0;padding:8px"><input data-tracking="'+esc(o.id)+'" placeholder="Tracking Code" value="'+esc(o.tracking_code||'')+'" style="display:block;width:100%;margin:6px 0;padding:8px"><input data-courier-status="'+esc(o.id)+'" placeholder="কুরিয়ার স্ট্যাটাস (যেমন: Pending, In Transit)" value="'+esc(o.courier_status||'')+'" style="display:block;width:100%;margin:6px 0;padding:8px"><button data-save-courier="'+esc(o.id)+'">কুরিয়ার তথ্য সেভ করুন</button><button type="button" data-book-steadfast="'+esc(o.id)+'" '+(o.consignment_id?'disabled':'')+'>Steadfast-এ বুক করুন</button><button type="button" data-track-steadfast="'+esc(o.id)+'" '+(!o.consignment_id?'disabled':'')+'>Steadfast স্ট্যাটাস আপডেট</button></div></div><div><b>'+money(o.total)+'</b><select data-status="'+o.id+'"><option value="pending" '+(o.status==='pending'?'selected':'')+'>Pending</option><option value="confirmed" '+(o.status==='confirmed'?'selected':'')+'>Confirmed</option><option value="shipped" '+(o.status==='shipped'?'selected':'')+'>Shipped</option><option value="delivered" '+(o.status==='delivered'?'selected':'')+'>Delivered</option><option value="cancelled" '+(o.status==='cancelled'?'selected':'')+'>Cancelled</option></select><button class="delete" data-order-delete="'+o.id+'">অর্ডার মুছুন</button></div></div>').join('')||'<p>কোনো অর্ডার নেই</p>';document.querySelectorAll('[data-status]').forEach(s=>s.onchange=async()=>{const r=await db.from('orders').update({status:s.value}).eq('id',s.dataset.status);if(r.error)return toast(r.error.message);await refresh()});document.querySelectorAll('[data-book-steadfast]').forEach(b=>b.onclick=()=>callSteadfast('book',b.dataset.bookSteadfast,b));document.querySelectorAll('[data-track-steadfast]').forEach(b=>b.onclick=()=>callSteadfast('track',b.dataset.trackSteadfast,b));document.querySelectorAll('[data-save-courier]').forEach(b=>b.onclick=async()=>{const id=b.dataset.saveCourier,consignment_id=document.querySelector('[data-consignment="'+id+'"]').value.trim(),tracking_code=document.querySelector('[data-tracking="'+id+'"]').value.trim(),courier_status=document.querySelector('[data-courier-status="'+id+'"]').value.trim();b.disabled=true;b.textContent='সেভ হচ্ছে...';const r=await db.from('orders').update({courier_name:'Steadfast',consignment_id,tracking_code,courier_status}).eq('id',id);if(r.error){b.disabled=false;b.textContent='কুরিয়ার তথ্য সেভ করুন';return toast('কুরিয়ার তথ্য সেভ হয়নি: '+r.error.message)}toast('কুরিয়ার তথ্য সেভ হয়েছে');await refresh()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=async()=>{const id=b.dataset.detail,el=$('detail-'+id);if(el.dataset.loaded){el.hidden=!el.hidden;return}const r=await db.from('order_items').select('product_name,unit_price,quantity').eq('order_id',id);el.innerHTML=r.error?esc(r.error.message):(r.data||[]).map(x=>'<small>'+esc(x.product_name)+' × '+x.quantity+' — '+money(x.unit_price*x.quantity)+'</small>').join('');el.dataset.loaded='1'});document.querySelectorAll('[data-order-delete]').forEach(b=>b.onclick=()=>deleteOrder(b.dataset.orderDelete))}async function deleteOrder(id){const order=orders.find(o=>String(o.id)===String(id));if(!order)return toast('অর্ডারটি পাওয়া যায়নি');if(!confirm('অর্ডার #'+id+' ('+order.customer_name+') স্থায়ীভাবে মুছে ফেলতে চান? এই অর্ডারের পণ্যের বিস্তারিতও মুছে যাবে।'))return;const b=document.querySelector('[data-order-delete="'+id+'"]');if(b){b.disabled=true;b.textContent='মুছে ফেলা হচ্ছে...'}const r=await db.from('orders').delete().eq('id',id).select('id');if(r.error){if(b){b.disabled=false;b.textContent='অর্ডার মুছুন'}return toast('অর্ডার মুছতে সমস্যা: '+r.error.message)}if(!r.data?.length){if(b){b.disabled=false;b.textContent='অর্ডার মুছুন'}return toast('অর্ডার মুছার অনুমতি নেই। Supabase SQL সেটআপ করুন।')}await refresh();toast('অর্ডার #'+id+' মুছে ফেলা হয়েছে')}function renderCustomers(){const map=new Map();orders.forEach(o=>{const k=o.phone||o.customer_name;if(!map.has(k))map.set(k,{name:o.customer_name,phone:o.phone,count:0,total:0});let x=map.get(k);x.count++;x.total+=Number(o.total||0)});const term=($('customerSearch').value||'').toLowerCase();$('customersList').innerHTML=[...map.values()].filter(x=>(x.name+' '+x.phone).toLowerCase().includes(term)).map(x=>'<div class="customer-row"><span><b>'+esc(x.name)+'</b><small>'+esc(x.phone)+' · '+x.count+'টি অর্ডার</small></span><b>'+money(x.total)+'</b></div>').join('')||'<p>কাস্টমার পাওয়া যায়নি</p>'}
async function loadLoginHistory(){if(!isMainAdmin)return;const list=$('loginHistoryList');list.innerHTML='<p class="muted">তথ্য লোড হচ্ছে...</p>';const {data,error}=await db.from('admin_login_history').select('email,logged_in_at').order('logged_in_at',{ascending:false}).limit(200);if(error){list.innerHTML='<p class="message">Login History পাওয়া যায়নি: '+esc(error.message)+'। Supabase SQL migration চালানো হয়েছে কি না দেখুন।</p>';return}list.innerHTML=data?.length?'<div class="login-history-table"><div class="login-history-row login-history-head"><b>ইমেইল</b><b>লগইনের সময়</b></div>'+data.map(x=>'<div class="login-history-row"><span>'+esc(x.email)+'</span><time>'+new Date(x.logged_in_at).toLocaleString('bn-BD',{dateStyle:'medium',timeStyle:'medium'})+'</time></div>').join('')+'</div>':'<p class="muted">এখনো কোনো লগইন রেকর্ড নেই।</p>'}async function loadStoreSettings(){const r=await db.from('store_settings').select('*').eq('id',1).maybeSingle();if(r.error){msg('settingsMsg','সেটিংস টেবিল তৈরি হয়নি। Supabase-এ store-settings.sql চালান।');return}const f=$('storeSettingsForm');if(!f)return;const s=r.data||{};for(const k of ['store_name','facebook_url','youtube_url','tiktok_url','ticker_message'])f.elements[k].value=s[k]||'';f.elements.ticker_enabled.checked=s.ticker_enabled===true;$('logoPreview').innerHTML=s.logo_url?'<img src="'+esc(s.logo_url)+'" alt="Business logo">':'<span>লোগো প্রিভিউ</span>';f.dataset.logoUrl=s.logo_url||''}
async function saveStoreSettings(e){e.preventDefault();const f=e.target,d=new FormData(f);msg('settingsMsg','সেভ হচ্ছে...');let logo_url=f.dataset.logoUrl||null;const file=f.elements.logo.files[0];if(file){if(file.size>5*1024*1024)return msg('settingsMsg','লোগোর সাইজ ৫ MB-এর মধ্যে রাখুন।');const ext=file.name.split('.').pop().toLowerCase(),path='branding/logo-'+Date.now()+'.'+ext;const up=await db.storage.from('product-images').upload(path,file,{upsert:true,contentType:file.type});if(up.error)return msg('settingsMsg',up.error.message);logo_url=db.storage.from('product-images').getPublicUrl(path).data.publicUrl}$('logoPreview').innerHTML=logo_url?'<img src="'+esc(logo_url)+'" alt="Business logo">':'<span>লোগো প্রিভিউ</span>';const row={id:1,store_name:d.get('store_name').trim(),logo_url,facebook_url:d.get('facebook_url').trim(),youtube_url:d.get('youtube_url').trim(),tiktok_url:d.get('tiktok_url').trim(),ticker_message:d.get('ticker_message').trim(),ticker_enabled:f.elements.ticker_enabled.checked,updated_at:new Date().toISOString()};const r=await db.from('store_settings').upsert(row,{onConflict:'id'});if(r.error)return msg('settingsMsg',r.error.message);f.dataset.logoUrl=logo_url||'';f.elements.logo.value='';msg('settingsMsg','সেটিংস সফলভাবে সেভ হয়েছে। নিউজ টিকারসহ পরিবর্তন ওয়েবসাইট রিফ্রেশ করলে দেখা যাবে।');toast('ব্র্যান্ডিং ও নিউজ টিকার আপডেট হয়েছে')}
